/**
 * Everything needed to render robots.txt.
 */
export interface WP_KizloRobots {
	rules: Array<WP_KizloRobotsGroup>
	/**
	 * The sitemap index URL, present only while the setting that includes it is on.
	 */
	sitemaps?: Array<string>
}

/**
 * Every directive for one user agent, grouped from the configured rules.
 */
export interface WP_KizloRobotsGroup {
	allow: Array<string>
	disallow: Array<string>
	user_agent: string
}

/**
 * A single robots.txt directive. SeoBase groups them by user agent when it renders the file.
 */
export interface WP_KizloRobotsRule {
	path: string
	rule: "allow" | "disallow"
	user_agent: string
}

/**
 * Head metadata and JSON-LD resolved from the Kizlo SEO settings and any per-item overrides.
 */
export interface WP_KizloSeo {
	head: {
		/**
		 * Null unless the item resolves to a schema.org Article type. Each field is present only when it resolves.
		 */
		article: {
			author?: string
			author_url?: string
			modified_time?: string
			published_time?: string
			section?: string
			tags?: Array<string>
		} | null
		canonical: string
		og: {
			/**
			 * Absent when no description resolves.
			 */
			description?: string
			/**
			 * Absent when no image resolves.
			 */
			image?: {
				alt: string | null
				height: number | null
				type: string | null
				url: string
				width: number | null
			}
			locale: string
			site_name: string
			title: string
			type: string
			url: string
		}
		robots: {
			follow: "follow" | "nofollow"
			index: "index" | "noindex"
			"max-image-preview": string
			"max-snippet": string
			"max-video-preview": string
		}
		title: string
		twitter: {
			card: "summary" | "summary_large_image"
			creator: string | null
			description?: string
			image?: string
			image_alt?: string
			/**
			 * The configured X/Twitter handle, or null when none is set.
			 */
			site: string | null
			title: string
		}
	}
	/**
	 * JSON-LD graph.
	 */
	schema: {
		"@context": string
		"@graph": Array<{
			[key: string]: unknown
		}>
	}
}

/**
 * SEO overrides for this entry. Every field is optional; an omitted field resolves from the post-type template, and an empty one clears the override.
 */
export interface WP_KizloSeoInput {
	/**
	 * schema.org Article subtype, or "none" to publish no Article node.
	 */
	article_type?: string
	canonical?: string
	description?: string
	nofollow?: boolean
	noindex?: boolean
	og?: {
		description?: string
		/**
		 * Image attachment ID. 0 clears the override.
		 */
		image_id?: number
		title?: string
	}
	title?: string
	twitter?: {
		description?: string
		/**
		 * Image attachment ID. 0 clears the override.
		 */
		image_id?: number
		title?: string
	}
	/**
	 * schema.org WebPage subtype.
	 */
	webpage_type?: string
}

