	logo: WP_KizloMediaImage | null
	logo_dark: WP_KizloMediaImage | null
	logo_icon: WP_KizloMediaImage | null
	logo_icon_dark: WP_KizloMediaImage | null
	logo_wordmark: WP_KizloMediaImage | null
	logo_wordmark_dark: WP_KizloMediaImage | null
