	/**
	 * schema.org Article subtype, or "none" to publish no Article node.
	 */
	article_type: string | null
	/**
	 * Ordered breadcrumb rows between the home crumb and the item.
	 */
	breadcrumbs: Array<number | "__parent__">
	comment_action_structure: string | null
	content_variables: Array<WP_KizloVariable>
	custom_fields: Array<WP_KizloCustomField>
	description_structure: string | null
	hierarchical: boolean
	/**
	 * True for the types Kizlo treats as built in, which cannot be deleted.
	 */
	internal: boolean
	/**
	 * True when Kizlo owns the WordPress registration and can edit it.
	 */
	kizlo_owned: boolean
	/**
	 * Plural label.
	 */
	name: string
	pathname_structure: string | null
	/**
	 * Null unless `kizlo_owned`.
	 */
	registration: WP_KizloPostTypeRegistration | null
	rest_api_enabled: boolean
	search_engine_visibility: boolean | null
	seo_enabled: boolean | null
	slug: string
	/**
	 * Which editor features the type has enabled.
	 */
	supports: {
		author: boolean
		comments: boolean
		"custom-fields": boolean
		editor: boolean
		excerpt: boolean
		"page-attributes": boolean
		"post-formats": boolean
		revisions: boolean
		thumbnail: boolean
		title: boolean
		trackbacks: boolean
	}
	title_structure: string | null
	/**
	 * schema.org WebPage subtype.
	 */
